import { z } from "zod";
import catalog from "../../../schemas/fixtures/validation_rules.json";

/**
 * The validation rule catalog. It is generated by the Python agent (services/agent-worker) and read from the shared JSON file,
 * so the settings screen can never list a rule the agent does not implement. A test pins the two together.
 */
export interface RuleInfo { id: string; name: string; description: string; severity: "info" | "warning" | "error"; params: Record<string, string> }
export const VALIDATION_RULES: readonly RuleInfo[] = catalog as RuleInfo[];

const decimal = z.string().trim().regex(/^\d+(\.\d+)?$/, "Enter a non-negative number");
const integer = z.string().trim().regex(/^\d{1,4}$/, "Enter a whole number");

/** Per-rule parameter validation. Unknown parameters are rejected so settings cannot be used to smuggle data. */
export function parseRuleParams(ruleId: string, raw: unknown): Record<string, string> {
  const info = VALIDATION_RULES.find((r) => r.id === ruleId);
  if (!info) throw new Error(`Unknown rule: ${ruleId}`);
  const shape = Object.fromEntries(Object.keys(info.params).map((k) => [k, k === "min_rows" ? integer : decimal]));
  return z.object(shape).strict().partial().parse(raw ?? {}) as Record<string, string>;
}
